    heap = [(0, source, [])]
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = {node: None for node in graph}
    while heap:
        current_distance, current_node, path_to_current = heapq.heappop(heap)
        if current_node == target:
            reconstructed_path = []
            while current_node is not None:
                reconstructed_path.append(current_node)
                current_node = path_to_current[current_node]
            reconstructed_path.reverse()
            return (current_distance, reconstructed_path)
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                path[neighbor] = current_node
                heapq.heappush(heap, (distance, neighbor, path_to_current + [current_node]))
