def shortest_path(graph, source, target):

    def heap_to_path(edges_heap, graph, path):
        while edges_heap:
            edge = heapq.heappop(edges_heap)
            node, weight = (edge[1], edge[0])
            if node in graph:
                path.append(node)
                graph[node].remove((node, weight))
                if not graph[node]:
                    del graph[node]
                for neighbor in edges_heap:
                    if neighbor[1] in graph[node]:
                        heapq.heappush(edges_heap, neighbor)
    edges_heap = [(0, source)]
    graph_graph = defaultdict(list)
    for node, edges in graph.items():
        for neighbor, weight in edges:
            graph_graph[node].append((weight, neighbor))
            graph_graph[neighbor].append((weight, node))
            heapq.heappush(edges_heap, (weight, neighbor))
    visited = set()
    distance = {node: float('inf') for node in graph}
    distance[source] = 0
    path = []
    while edges_heap:
        weight, node = heapq.heappop(edges_heap)
        if node not in visited:
            visited.add(node)
            if node == target:
                path_to_node = path[:]
                path_to_node.append(node)
                return (distance[target], path_to_node)
            for neighbor, _ in graph[node]:
                new_weight = weight + neighbor
                if new_weight < distance[neighbor]:
                    distance[neighbor] = new_weight
                    heapq.heappush(edges_heap, (new_weight, neighbor))
                    path_to_node = path[:]
                    path_to_node.append(node)
                    path_to_node.append(neighbor)
            heap_to_path(edges_heap, graph_graph, path_to_node)
            path = path_to_node
    if target not in distance:
        return (float('inf'), None)
    else:
        return (distance[target], path)
